// ── 样式工具 ──────────────────────────────────────────────────────────
const COLORS = {
  red: '#ff4d4f',
  orange: '#fa8c16',
  yellow: '#faad14',
  green: '#52c41a',
  blue: '#1677ff',
  gray: '#8c8c8c',
};

const Section = ({ title, children }) => (
  <div style={{ marginBottom: 28 }}>
    <div
      style={{
        fontSize: 14,
        fontWeight: 700,
        color: '#262626',
        borderLeft: '3px solid #1677ff',
        paddingLeft: 10,
        marginBottom: 14,
      }}
    >
      {title}
    </div>
    {children}
  </div>
);

const WarningCard = ({ level = 'orange', icon, title, children, evidence }) => {
  const color = COLORS[level];
  const bg =
    level === 'red'
      ? '#fff1f0'
      : level === 'orange'
        ? '#fff7e6'
        : level === 'yellow'
          ? '#fffbe6'
          : '#f6ffed';
  const border =
    level === 'red'
      ? '#ffa39e'
      : level === 'orange'
        ? '#ffd591'
        : level === 'yellow'
          ? '#ffe58f'
          : '#b7eb8f';
  return (
    <div
      style={{
        background: bg,
        border: `1px solid ${border}`,
        borderLeft: `3px solid ${color}`,
        borderRadius: 6,
        padding: '12px 16px',
        marginBottom: 12,
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 8,
          marginBottom: evidence || children ? 8 : 0,
        }}
      >
        <span style={{ fontSize: 15 }}>{icon}</span>
        <span style={{ fontSize: 13, fontWeight: 600, color: '#262626' }}>{title}</span>
      </div>
      {children && (
        <div
          style={{
            fontSize: 12,
            color: '#595959',
            lineHeight: 1.8,
            marginBottom: evidence ? 8 : 0,
          }}
        >
          {children}
        </div>
      )}
      {evidence && (
        <div
          style={{
            background: 'rgba(0,0,0,0.04)',
            borderRadius: 4,
            padding: '6px 10px',
            fontSize: 11,
            color: '#8c8c8c',
            lineHeight: 1.7,
          }}
        >
          {evidence}
        </div>
      )}
    </div>
  );
};

